 private static function need(bool $ok):void{if(!$ok)throw new DomainException('Ursprüngliche HGB-Einzelwerte getrennt vom steuerlichen Sammelposten prüfen.');}
 private static function keys(mixed $v,array $fields):void{self::need(is_array($v)&&count($v)===count($fields)&&!array_diff(array_keys($v),$fields));}
