 private static function document(mixed $v):void{self::keys($v,['document_id','revision','sha256']);self::need(is_string($v['document_id'])&&preg_match('/^[a-f0-9]{32}$/D',$v['document_id'])===1&&is_int($v['revision'])&&$v['revision']>=1&&is_string($v['sha256'])&&preg_match('/^[a-f0-9]{64}$/D',$v['sha256'])===1);}
