  self::need($book['schema']===1&&$book['club_id']===$s['club_id']&&$book['pool_id']===$s['pool_id']&&$book['year']===$year&&in_array($year,[2025,2026],true)&&$book['basis']==='original_individual_hgb_register'&&$book['confirmed']===true);self::document($book['document']);self::note($book['reason']);self::need(is_array($book['items'])&&array_is_list($book['items'])&&count($book['items'])===count($proof['eligible_items']));$totals=array_fill_keys(array_keys($proof['fiscal']),0);$seen=[];
  foreach($book['items'] as $r){
   self::keys($r,['item_id','acquired_on','original_cost_cents','original_life_months','original_residual_cents','cost_opening_cents','additions_cents','cost_closing_cents','accumulated_opening_cents','depreciation_cents','accumulated_closing_cents','book_opening_cents','book_closing_cents','document','reason','confirmed']);self::need(is_string($r['item_id'])&&in_array($r['item_id'],$proof['eligible_items'],true)&&!isset($seen[$r['item_id']]));$seen[$r['item_id']]=true;$original=null;foreach($s['population'] as $row)if($row['item_id']===$r['item_id'])$original=$row;self::document($r['document']);self::note($r['reason']);self::need($r['confirmed']===true&&$r['acquired_on']===$original['acquired_on']&&$r['acquired_on']===$formed.'-01-01'&&$r['original_life_months']===60&&$r['original_residual_cents']===0);$cost=$r['original_cost_cents'];self::money($cost);self::need($cost===$original['basis_cents']);$before=intdiv($cost*$age+2,5);$after=intdiv($cost*($age+1)+2,5);$fields=['cost_opening_cents'=>$age?$cost:0,'additions_cents'=>$age?0:$cost,'cost_closing_cents'=>$cost,'accumulated_opening_cents'=>$before,'depreciation_cents'=>$after-$before,'accumulated_closing_cents'=>$after,'book_opening_cents'=>$age?$cost-$before:0,'book_closing_cents'=>$cost-$after];foreach($fields as $key=>$value){self::money($r[$key]);self::need($r[$key]===$value);$totals[$key]+=$value;self::money($totals[$key]);}
  }
