  else{self::keys($previous,['schema','pool_proof','book_source','previous','hgb','journal_verified','export_authorized','sha256']);self::need(is_array($previous['pool_proof'])&&is_array($previous['book_source'])&&($previous['previous']===null||is_array($previous['previous'])));$prior=self::verify($previous['pool_proof'],$previous['book_source'],$previous['previous'],$depth+1);self::need(PoolOriginalSources::fingerprint($prior)===PoolOriginalSources::fingerprint($previous)&&PoolOriginalSources::fingerprint($prior['pool_proof'])===PoolOriginalSources::fingerprint($proof['previous'])&&$prior['book_source']['year']+1===$year);$previous=$prior;$old=[];foreach($prior['book_source']['items'] as $r)$old[$r['item_id']]=$r;foreach($book['items'] as $r){$original=$old[$r['item_id']];foreach(['item_id','acquired_on','original_cost_cents','original_life_months','original_residual_cents'] as $k)self::need($r[$k]===$original[$k]);self::need($r['book_opening_cents']===$original['book_closing_cents']&&$r['accumulated_opening_cents']===$original['accumulated_closing_cents']);}}
  $out=['schema'=>1,'pool_proof'=>$proof,'book_source'=>$book,'previous'=>$previous,'hgb'=>$totals,'journal_verified'=>false,'export_authorized'=>false];return $out+['sha256'=>PoolOriginalSources::fingerprint($out)];
 }
}
